INSERT INTO listing_media (listing_id, media_type, url, sort_order)
SELECT l.id, 'photo', image.url, image.ordinality::integer - 1
FROM listings l
JOIN fixtures f ON l.tags @> jsonb_build_array('umutungo-fixture:' || f.fixture_id)
CROSS JOIN LATERAL jsonb_array_elements_text(f.images) WITH ORDINALITY AS image(url, ordinality)
WHERE l.owner_id = '00000000-0000-4000-8000-00000000d001'
  AND l.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM listing_media m WHERE m.listing_id = l.id);
